"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[17776],{82436:e=>{e.exports=JSON.parse('{"tag":{"label":"gerbils","permalink":"/docs/tags/gerbils","allTagsPath":"/docs/tags","count":21,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Gerbils/getting-started/gerbil-basic-care","title":"Basic Care","description":"Gerbil Basic Care","permalink":"/docs/Gerbils/getting-started/gerbil-basic-care"},{"id":"Gerbils/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Gerbils","description":"An overview of the most common health issues affecting pet gerbils, including respiratory infections, scent gland tumors, tail slip, and Tyzzer\'s disease.","permalink":"/docs/Gerbils/illnesses-and-conditions/common-health-issues"},{"id":"Gerbils/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in gerbils, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the critical role of chewing materials.","permalink":"/docs/Gerbils/health-and-wellness/dental-health"},{"id":"Gerbils/illnesses-and-conditions/diabetes","title":"diabetes","description":"A guide to diabetes in gerbils, a common condition often linked to diet, covering the signs, causes, and the importance of dietary management for prevention and care.","permalink":"/docs/Gerbils/illnesses-and-conditions/diabetes"},{"id":"Gerbils/getting-started/essential-supplies","title":"Essential Supplies for Pet Gerbils","description":"A comprehensive checklist of the essential supplies needed to set up a safe, enriching, and appropriate habitat for pet gerbils.","permalink":"/docs/Gerbils/getting-started/essential-supplies"},{"id":"Gerbils/health-and-wellness/eye-and-vision-issues","title":"eye-and-vision-issues","description":"A guide to common eye and vision issues in gerbils, explaining the significance of porphyrin (red tears), the causes of eye infections, and how to prevent irritation.","permalink":"/docs/Gerbils/health-and-wellness/eye-and-vision-issues"},{"id":"Gerbils/health-and-wellness/gi-health","title":"gi-health","description":"A guide to gastrointestinal (GI) health in gerbils, covering common issues like diarrhea, the importance of a stable diet, and the serious threat of Tyzzer\'s disease.","permalink":"/docs/Gerbils/health-and-wellness/gi-health"},{"id":"Gerbils/getting-started/grooming-your-gerbil","title":"Grooming Your Pet Gerbil","description":"A guide to the minimal grooming needs of pet gerbils, including the role of sand baths, brushing, and nail care.","permalink":"/docs/Gerbils/getting-started/grooming-your-gerbil"},{"id":"Gerbils/getting-started/gerbil-habitat","title":"Habitat","description":"Creating the right environment is one of the most important things you can do for your gerbils. As natural burrowers, their habitat needs to accommodate their instinct to dig. A proper setup will...","permalink":"/docs/Gerbils/getting-started/gerbil-habitat"},{"id":"Gerbils/health-and-wellness/home-health-care","title":"Home Health Care for Pet Gerbils","description":"A guide to performing regular at-home health checks for your pet gerbils to monitor their well-being and catch early signs of illness.","permalink":"/docs/Gerbils/health-and-wellness/home-health-care"},{"id":"Gerbils/getting-started/is-a-gerbil-right-for-me","title":"Is a Gerbil Right for You?","description":"Gerbils are curious, active, and social animals that can make wonderful pets for the right family. However, like any animal, they have specific needs that must be met to ensure they live a happy and...","permalink":"/docs/Gerbils/getting-started/is-a-gerbil-right-for-me"},{"id":"Gerbils/illnesses-and-conditions/kidney-and-urinary-disorders","title":"kidney-and-urinary-disorders","description":"A guide to kidney and urinary disorders in gerbils, with a focus on chronic kidney disease (nephritis) in older gerbils, covering the signs, causes, and supportive care.","permalink":"/docs/Gerbils/illnesses-and-conditions/kidney-and-urinary-disorders"},{"id":"Gerbils/breeds-and-genetics/know-your-gerbil-breeds","title":"Know Your Gerbil Breeds","description":"An overview of the two species of gerbils commonly kept as pets, and the wide variety of coat colors found in Mongolian gerbils.","permalink":"/docs/Gerbils/breeds-and-genetics/know-your-gerbil-breeds"},{"id":"Gerbils/getting-started/gerbil-nutrition","title":"Nutrition","description":"A balanced diet is essential for a gerbil\'s health and longevity. Unlike some other small pets, gerbils are prone to obesity and selective eating, so it\'s important to provide a diet that is both...","permalink":"/docs/Gerbils/getting-started/gerbil-nutrition"},{"id":"Gerbils/health-and-wellness/parasites","title":"parasites","description":"A guide to parasites affecting gerbils, including common external parasites like mites and fleas, and internal parasites like pinworms.","permalink":"/docs/Gerbils/health-and-wellness/parasites"},{"id":"Gerbils/getting-started/proper-handling","title":"Proper Handling of Pet Gerbils","description":"A guide to safely and confidently handling pet gerbils, with tips for building trust and the critical importance of never grabbing their tail.","permalink":"/docs/Gerbils/getting-started/proper-handling"},{"id":"Gerbils/health-and-wellness/respiratory-issues","title":"respiratory-issues","description":"A guide to respiratory infections in gerbils, covering the common causes, signs of illness, and the importance of a clean, well-ventilated environment and proper bedding for prevention.","permalink":"/docs/Gerbils/health-and-wellness/respiratory-issues"},{"id":"Gerbils/breeds-and-genetics/sexing-your-gerbil","title":"Sexing Your Pet Gerbil","description":"A guide to determining the sex of a pet gerbil using anogenital distance and other physical characteristics.","permalink":"/docs/Gerbils/breeds-and-genetics/sexing-your-gerbil"},{"id":"Gerbils/illnesses-and-conditions/tail-slip","title":"tail-slip","description":"An essential guide to tail slip in gerbils, a common and serious injury caused by improper handling, explaining the mechanism, necessary treatment, and how to prevent it.","permalink":"/docs/Gerbils/illnesses-and-conditions/tail-slip"},{"id":"Gerbils/health-and-wellness/understanding-gerbil-behavior","title":"understanding-gerbil-behavior","description":"Gerbils are highly social, curious animals that communicate through a combination of body language, scent marking, and vocalizations.","permalink":"/docs/Gerbils/health-and-wellness/understanding-gerbil-behavior"}],"unlisted":false}}')}}]);